from copy import deepcopy
from amounts import valid_amount

def refund(orders, ledger, order_id, request_id, amount):
    valid_amount(amount)
    if request_id in ledger:
        entry=ledger[request_id]
        if entry["order_id"]!=order_id or entry["amount"]!=amount: raise ValueError("conflict")
        return deepcopy(entry)
    if order_id not in orders: raise ValueError("unknown order")
    order=orders[order_id]
    if order["status"] not in ("paid","partially_refunded"): raise ValueError("invalid state")
    total=order["refunded"]+amount
    if total>order["paid"]: raise ValueError("excess")
    entry={"order_id":order_id,"amount":amount,"refunded_total":total}
    order["refunded"]=total
    order["status"]="refunded" if total==order["paid"] else "partially_refunded"
    ledger[request_id]=deepcopy(entry)
    return deepcopy(entry)

